\begin{lemma}[Integral closure is ring]
\label{algebra-lemma-integral-closure-is-ring}
\source{stacks:00GO}
\href{https://stacks.math.columbia.edu/tag/00GO}{\texttt{Stacks tag 00GO}}
\group{algebra}

Let $R \to S$ be a ring homomorphism.
The set
$$
S' = \{s \in S \mid s\text{ is integral over }R\}
$$
is an $R$-subalgebra of $S$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-characterize-integral, algebra-lemma-finite-is-integral}

This is clear from Lemmas \ref{algebra-lemma-characterize-integral}
and \ref{algebra-lemma-finite-is-integral}.
\end{proof}

\begin{lemma}[Finite product integral]
\label{algebra-lemma-finite-product-integral}
\source{stacks:0CY8}
\href{https://stacks.math.columbia.edu/tag/0CY8}{\texttt{Stacks tag 0CY8}}
\group{algebra}

Let $R_i\to S_i$ be ring maps $i = 1, \ldots, n$.
Let $R$ and $S$ denote the product of the $R_i$ and $S_i$ respectively.
Then an element $s = (s_1, \ldots, s_n) \in S$ is integral over $R$
if and only if each $s_i$ is integral over $R_i$.
\end{lemma}

