\begin{definition}[Integral closure]
\label{algebra-definition-integral-closure}
\source{stacks:00GP}
\href{https://stacks.math.columbia.edu/tag/00GP}{\texttt{Stacks tag 00GP}}
\group{algebra}

\uses{algebra-lemma-integral-closure-is-ring}
Let $R \to S$ be a ring map.
The ring $S' \subset S$ of elements integral over
$R$, see Lemma \ref{algebra-lemma-integral-closure-is-ring},
is called the {\it integral closure} of $R$
in $S$. If $R \subset S$ we say that $R$ is
{\it integrally closed} in $S$ if $R = S'$.
\end{definition}

In particular, we see that $R \to S$ is integral if and only
if the integral closure of $R$ in $S$ is all of $S$.

